import React, { useEffect, useState } from 'react';
import axios from 'axios';
import DatePicker from 'react-datepicker';
import "react-datepicker/dist/react-datepicker.css";

function ReservayEquipo() {
  const [date, setDate] = useState(null);
  const [time, setTime] = useState('');
  const [canchas, setCanchas] = useState([]);
  const [equipos, setEquipos] = useState([]);
  const [selectedCancha, setSelectedCancha] = useState('');
  const [selectedEquipo, setSelectedEquipo] = useState('');
  const [userEmail, setUserEmail] = useState('');
  const [sanctioned, setSanctioned] = useState({ isSanctioned: false, fechaFin: '' });
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchInitialData = async () => {
      try {
        const token = localStorage.getItem('token');
        const profileResponse = await axios.get('http://localhost:5000/profile', {
          headers: { Authorization: `Bearer ${token}` }
        });

        const email = profileResponse.data.email;
        setUserEmail(email);

        // Verificar si el usuario está sancionado
        const sanctionResponse = await axios.get(`http://localhost:5000/api/usuarios/${email}/sancion-activa`, {
          headers: { Authorization: `Bearer ${token}` }
        });

        if (sanctionResponse.data.isSanctioned) {
          setSanctioned({
            isSanctioned: true,
            fechaFin: sanctionResponse.data.fechaFinSancion
          });
        } else {
          setSanctioned({ isSanctioned: false, fechaFin: '' });
        }

        // Obtener canchas
        const canchasResponse = await axios.get('http://localhost:5000/api/canchas', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setCanchas(canchasResponse.data);
      } catch (err) {
        console.error('Error al cargar los datos iniciales:', err);
        setError('Hubo un error al cargar los datos. Intenta nuevamente.');
      }
    };

    fetchInitialData();
  }, []);

  const handleReserva = async () => {
    if (sanctioned.isSanctioned) {
      setError(`No puedes reservar. Estás sancionado hasta el ${sanctioned.fechaFin}.`);
      return;
    }

    try {
      const token = localStorage.getItem('token');
      await axios.post(
        'http://localhost:5000/api/reservas',
        {
          date,
          time,
          cancha: selectedCancha,
          equipo: selectedEquipo
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      alert('Reserva realizada con éxito.');
    } catch (err) {
      console.error('Error al realizar la reserva:', err);
      setError('Hubo un problema al realizar la reserva. Intenta nuevamente.');
    }
  };

  return (
    <div>
      <h1>Reservar Cancha</h1>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      {sanctioned.isSanctioned ? (
        <p style={{ color: 'red' }}>
          No puedes realizar reservas. Tu sanción termina el {sanctioned.fechaFin}.
        </p>
      ) : (
        <>
          <label>Fecha:</label>
          <DatePicker
            selected={date}
            onChange={(date) => setDate(date)}
            minDate={new Date()}
            filterDate={(date) => date.getDay() !== 0 && date.getDay() !== 6} // Evitar fines de semana
          />

          <label>Hora:</label>
          <select value={time} onChange={(e) => setTime(e.target.value)}>
            <option value="">Selecciona una hora</option>
            <option value="10:00">10:00</option>
            <option value="12:00">12:00</option>
          </select>

          <label>Cancha:</label>
          <select value={selectedCancha} onChange={(e) => setSelectedCancha(e.target.value)}>
            <option value="">Selecciona una cancha</option>
            {canchas.map((cancha) => (
              <option key={cancha.id} value={cancha.id}>
                {cancha.nombre}
              </option>
            ))}
          </select>

          <label>Equipo:</label>
          <select value={selectedEquipo} onChange={(e) => setSelectedEquipo(e.target.value)}>
            <option value="">Selecciona un equipo</option>
            {equipos.map((equipo) => (
              <option key={equipo.id} value={equipo.id}>
                {equipo.nombre}
              </option>
            ))}
          </select>

          <button onClick={handleReserva}>Reservar</button>
        </>
      )}
    </div>
  );
}

export default ReservayEquipo;
